/**
 * A panel's true UV -> mesh-local position, by bilinear interpolation of the sampled
 * mesh. Outside the grid domain the edge cells are extended; the seam clamp keeps every
 * footprint inside the clamp rect, which the domain covers, so that only happens for an
 * intermediate step of a ray cast.
 */
/**
 * Interpolate a panel's sampled mesh grid at (u,v).
 *
 * Pass 18: the grid is now passed IN rather than read from this module, because a second
 * garment has its own. Everything else about the function is unchanged.
 */
export function panelUvToMesh(
  p: Panel,
  grid: number[],
  u: number,
  v: number
): { x: number; y: number; z: number } {
  const fu = ((u - p.gridU0) / (p.gridU1 - p.gridU0)) * (p.gnu - 1)
  const fv = ((v - p.gridV0) / (p.gridV1 - p.gridV0)) * (p.gnv - 1)
  const i = Math.max(0, Math.min(p.gnu - 2, Math.floor(fu)))
  const j = Math.max(0, Math.min(p.gnv - 2, Math.floor(fv)))
  const a = fu - i
  const b = fv - j
  const k00 = p.gridAt + (i * p.gnv + j) * 3
  const k01 = p.gridAt + (i * p.gnv + j + 1) * 3
  const k10 = p.gridAt + ((i + 1) * p.gnv + j) * 3
  const k11 = p.gridAt + ((i + 1) * p.gnv + j + 1) * 3
  const w00 = (1 - a) * (1 - b)
  const w10 = a * (1 - b)
  const w01 = (1 - a) * b
  const w11 = a * b
  return {
    x: grid[k00] * w00 + grid[k10] * w10 + grid[k01] * w01 + grid[k11] * w11,
    y: grid[k00 + 1] * w00 + grid[k10 + 1] * w10 + grid[k01 + 1] * w01 + grid[k11 + 1] * w11,
    z: grid[k00 + 2] * w00 + grid[k10 + 2] * w10 + grid[k01 + 2] * w01 + grid[k11 + 2] * w11,
  }
}
